// Turns whatever was thrown into an exception type, message, and stack.

const MAX_CAUSES = 5;
const MAX_MESSAGE = 4_000;

export interface Exception {
  type: string;
  message: string;
  stacktrace?: string;
}

interface ErrorLike {
  name?: unknown;
  message?: unknown;
  stack?: unknown;
  cause?: unknown;
}

function isErrorLike(value: unknown): value is ErrorLike {
  return typeof value === "object" && value !== null && "message" in value && ("name" in value || "stack" in value);
}

// Firefox and Safari stacks have no `Type: message` line, so it is added to
// keep every browser's stack readable on its own.
function stackOf(error: ErrorLike, type: string, message: string): string | undefined {
  if (typeof error.stack !== "string" || !error.stack) return undefined;
  return error.stack.startsWith(`${type}`) ? error.stack : `${type}: ${message}\n${error.stack}`;
}

function describe(value: unknown): string {
  if (typeof Event !== "undefined" && value instanceof Event) {
    const target = value.target as { tagName?: string } | null;
    return `Event \`${value.type}\`${target?.tagName ? ` on <${target.tagName.toLowerCase()}>` : ""}`;
  }
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}

export function toException(value: unknown, fallbackType = "Error"): Exception {
  if (isErrorLike(value)) {
    const type = typeof value.name === "string" && value.name ? value.name : "Error";
    const message = String(value.message ?? "").slice(0, MAX_MESSAGE);
    let stacktrace = stackOf(value, type, message);
    // The causes follow the error, as Node prints them.
    let cause = value.cause;
    for (let depth = 0; depth < MAX_CAUSES && cause !== undefined && cause !== null; depth += 1) {
      const inner = toException(cause);
      stacktrace = `${stacktrace ?? `${type}: ${message}`}\nCaused by: ${inner.stacktrace ?? `${inner.type}: ${inner.message}`}`;
      cause = isErrorLike(cause) ? cause.cause : undefined;
    }
    return { message, stacktrace, type };
  }
  if (typeof value === "string") return { message: value.slice(0, MAX_MESSAGE), type: fallbackType };
  return { message: describe(value).slice(0, MAX_MESSAGE), type: fallbackType };
}

import type { Attributes, AttributeValue, Context } from "@opentelemetry/api";
import type { LogRecordProcessor, SdkLogRecord } from "@opentelemetry/sdk-logs";
import type { ReadableSpan, Span, SpanProcessor } from "@opentelemetry/sdk-trace";
import type { User } from "./types.js";

// Attributes added to every log and span: the user, the route, and any set
// with `setAttributes`.
export class Scope {
  private attributes: Attributes = {};

  set(key: string, value: AttributeValue | undefined): void {
    if (value === undefined || value === null) delete this.attributes[key];
    else this.attributes[key] = value;
  }

  setUser(user: User | null): void {
    this.set("user.id", user?.id);
    this.set("user.email", user?.email);
    this.set("user.name", user?.name);
    this.set("user.full_name", user?.fullName);
    this.set("user.roles", user?.roles);
  }

  all(): Attributes {
    return this.attributes;
  }
}

export class ScopeLogRecordProcessor implements LogRecordProcessor {
  constructor(private readonly scope: Scope) {}

  onEmit(record: SdkLogRecord, _context?: Context): void {
    for (const [key, value] of Object.entries(this.scope.all())) {
      if (value !== undefined && record.attributes[key] === undefined) record.setAttribute(key, value);
    }
  }

  async forceFlush(): Promise<void> {}
  async shutdown(): Promise<void> {}
}

export class ScopeSpanProcessor implements SpanProcessor {
  constructor(private readonly scope: Scope) {}

  onStart(span: Span, _context: Context): void {
    for (const [key, value] of Object.entries(this.scope.all())) {
      if (value !== undefined) span.setAttribute(key, value);
    }
  }

  onEnd(_span: ReadableSpan): void {}
  async forceFlush(): Promise<void> {}
  async shutdown(): Promise<void> {}
}

import type { Client } from "./client.js";

// The running client, kept apart from init so the capture functions stay
// small: an application can import them eagerly and load init in a chunk of
// its own.
let current: Client | null = null;

export function currentClient(): Client | null {
  return current;
}

export function setCurrentClient(client: Client | null): void {
  current = client;
}

import type { UrlPattern } from "./types.js";

export function matches(value: string, patterns: readonly UrlPattern[]): boolean {
  return patterns.some((pattern) => (typeof pattern === "string" ? value.includes(pattern) : pattern.test(value)));
}

import type { Attributes, TextMapPropagator } from "@opentelemetry/api";
import type { LogRecordProcessor } from "@opentelemetry/sdk-logs";
import type { SpanProcessor } from "@opentelemetry/sdk-trace";

export type UrlPattern = string | RegExp;

// An error about to be sent. `beforeSend` may change it or drop it.
export interface ErrorEvent {
  type: string;
  message: string;
  stacktrace?: string;
  // Where the error was caught: `onerror`, `onunhandledrejection`, `react`,
  // or `manual`.
  mechanism: string;
  handled: boolean;
  attributes: Attributes;
}

export interface Breadcrumb {
  // `navigation`, `click`, `console`, `http`, or a name of your own.
  category: string;
  message: string;
  level?: "debug" | "info" | "warning" | "error";
  timestamp?: number;
  data?: Record<string, string | number | boolean>;
}

export interface User {
  id?: string;
  email?: string;
  name?: string;
  fullName?: string;
  roles?: string[];
}

export interface InitOptions {
  // Name of the application, sent as `service.name`.
  service: string;
  // Superlog ingest key. Sent as `Authorization: Bearer <key>`.
  ingestKey?: string;
  // OTLP/HTTP endpoint. `/v1/logs` and `/v1/traces` are added to it.
  // Defaults to Superlog, `https://superlog.sh/api/ingest`.
  endpoint?: string;
  // Headers for every export request, for any OTLP backend.
  headers?: Record<string, string>;
  // Version of the build, sent as `service.version`. Source maps are matched
  // by it.
  release?: string;
  // Sent as `deployment.environment.name`.
  environment?: string;
  resourceAttributes?: Attributes;
  // Cross-origin URLs that receive `traceparent`. Same-origin requests always
  // do. Other origins never do unless listed, since an unexpected header can
  // fail a CORS preflight.
  tracePropagationTargets?: UrlPattern[];
  // Requests that are not traced or recorded as breadcrumbs, such as
  // analytics. The export endpoint is never traced.
  ignoreUrls?: UrlPattern[];
  // How trace context is written into requests. Default: W3C trace context
  // and baggage. Add a propagator when a backend reads another header.
  propagators?: TextMapPropagator[];
  // Share of traces kept, from 0 to 1. Errors are always sent.
  tracesSampleRate?: number;
  // Errors whose message matches are dropped. Strings match anywhere.
  ignoreErrors?: UrlPattern[];
  // Errors whose stack only has frames from these URLs are dropped.
  denyUrls?: UrlPattern[];
  beforeSend?: (event: ErrorEvent) => ErrorEvent | null;
  beforeBreadcrumb?: (breadcrumb: Breadcrumb) => Breadcrumb | null;
  maxBreadcrumbs?: number;
  // Errors sent per minute at most, so a loop cannot flood the backend.
  maxErrorsPerMinute?: number;
  // Removes secrets from URLs before they are recorded.
  sanitizeUrl?: (url: string) => string;
  instrumentations?: {
    // Traces fetch and XMLHttpRequest calls. Default on.
    fetch?: boolean;
    xhr?: boolean;
    // Sends a log for each page load and navigation. Default on.
    navigation?: boolean;
    // Sends page load timing. Default on.
    navigationTiming?: boolean;
    // Sends LCP, INP, CLS, FCP, and TTFB. Default on.
    webVitals?: boolean;
    // Records clicks and console output as breadcrumbs. Default on.
    clicks?: boolean;
    console?: boolean;
  };
  // Extra processors, such as an exporter to a second backend.
  logRecordProcessors?: LogRecordProcessor[];
  spanProcessors?: SpanProcessor[];
  // Session length limits, in milliseconds.
  session?: { inactivityTimeout?: number; maxDuration?: number };
  disabled?: boolean;
  debug?: boolean;
}

import type { Attributes } from "@opentelemetry/api";
import { SeverityNumber } from "@opentelemetry/api-logs";
import type { Logger } from "@opentelemetry/api-logs";
import type { Breadcrumbs } from "./breadcrumbs.js";
import { debugIdsFor } from "./debug-ids.js";
import { type Exception, toException } from "./exception.js";
import { matches } from "./patterns.js";
import type { Scope } from "./scope.js";
import type { ErrorEvent, InitOptions, UrlPattern } from "./types.js";

// Browser noise that says nothing about the application: cross-origin script
// errors without details and the ResizeObserver loop notice.
const DEFAULT_IGNORE_ERRORS: UrlPattern[] = [
  /^Script error\.?$/,
  /^ResizeObserver loop (?:limit exceeded|completed with undelivered notifications)/,
];

const EXTENSION_URL = /(?:chrome|moz|safari|safari-web|ms-browser)-extension:\/\//;
const FRAME_URL = /(?:\(|@|\s)((?:https?|[a-z-]+-extension|file):\/\/[^\s)]+?)(?::\d+){1,2}\)?\s*$/;
const DEDUPE_WINDOW_MS = 1_000;

export interface CaptureOptions {
  attributes?: Attributes;
  handled?: boolean;
  mechanism?: string;
}

export class Client {
  private recent: { key: string; at: number } | null = null;
  private sent: number[] = [];

  constructor(
    private readonly options: InitOptions,
    private readonly logger: Logger,
    readonly breadcrumbs: Breadcrumbs,
    readonly scope: Scope,
  ) {}

  captureException(value: unknown, options: CaptureOptions = {}): void {
    this.capture(toException(value), options);
  }

  captureMessage(message: string, level: "info" | "warning" | "error" = "info", attributes?: Attributes): void {
    const severity = { error: SeverityNumber.ERROR, info: SeverityNumber.INFO, warning: SeverityNumber.WARN }[level];
    this.logger.emit({
      attributes: { ...attributes, ...this.breadcrumbAttributes(), ...this.pageAttributes() },
      body: message,
      severityNumber: severity,
      severityText: level.toUpperCase(),
    });
  }

  private capture(exception: Exception, options: CaptureOptions): void {
    let event: ErrorEvent | null = {
      attributes: { ...options.attributes },
      handled: options.handled ?? true,
      mechanism: options.mechanism ?? "manual",
      message: exception.message,
      stacktrace: exception.stacktrace,
      type: exception.type,
    };
    if (this.ignored(event) || this.duplicate(event) || this.overLimit()) return;
    if (this.options.beforeSend) {
      try {
        event = this.options.beforeSend(event);
      } catch {
        // A failing hook sends the error as it was.
      }
      if (!event) return;
    }
    this.sent.push(Date.now());
    this.logger.emit({
      attributes: {
        ...this.pageAttributes(),
        ...event.attributes,
        ...this.breadcrumbAttributes(),
        "exception.handled": event.handled,
        "exception.mechanism": event.mechanism,
        "exception.message": event.message,
        "exception.type": event.type,
        ...(event.stacktrace ? { "exception.stacktrace": event.stacktrace } : {}),
        ...debugIdAttributes(event.stacktrace),
      },
      // The body repeats the message so backends that group logs by body
      // still tell errors apart.
      body: event.message || event.type,
      eventName: "exception",
      severityNumber: SeverityNumber.ERROR,
      severityText: "ERROR",
    });
  }

  private ignored(event: ErrorEvent): boolean {
    const text = event.message || event.type;
    if (matches(text, [...DEFAULT_IGNORE_ERRORS, ...(this.options.ignoreErrors ?? [])])) return true;
    if (matches(`${event.type}: ${event.message}`, this.options.ignoreErrors ?? [])) return true;
    const urls = framesUrls(event.stacktrace);
    if (urls.length === 0) return false;
    // Errors raised only by browser extensions or denied scripts are not the
    // application's.
    const denied = this.options.denyUrls ?? [];
    return urls.every((url) => EXTENSION_URL.test(url) || matches(url, denied));
  }

  // The same error raised again at once, as by a handler that runs on every
  // frame, is sent once.
  private duplicate(event: ErrorEvent): boolean {
    const key = `${event.type}\n${event.message}\n${event.stacktrace ?? ""}`;
    const now = Date.now();
    const repeated = this.recent?.key === key && now - this.recent.at < DEDUPE_WINDOW_MS;
    this.recent = { at: now, key };
    return repeated;
  }

  private overLimit(): boolean {
    const now = Date.now();
    this.sent = this.sent.filter((at) => now - at < 60_000);
    return this.sent.length >= (this.options.maxErrorsPerMinute ?? 30);
  }

  private breadcrumbAttributes(): Attributes {
    const serialized = this.breadcrumbs.serialize();
    return serialized ? { "app.breadcrumbs": serialized } : {};
  }

  private pageAttributes(): Attributes {
    if (typeof location === "undefined") return {};
    const url = this.options.sanitizeUrl ? this.options.sanitizeUrl(location.href) : location.href;
    return { "url.full": url };
  }
}

function debugIdAttributes(stacktrace: string | undefined): Attributes {
  const debugIds = debugIdsFor(stacktrace);
  return debugIds ? { "app.debug_ids": JSON.stringify(debugIds) } : {};
}

function framesUrls(stacktrace: string | undefined): string[] {
  if (!stacktrace) return [];
  const urls: string[] = [];
  for (const line of stacktrace.split("\n")) {
    const match = line.trim().match(FRAME_URL);
    if (match?.[1]) urls.push(match[1]);
  }
  return urls;
}

import { context, propagation, trace } from "@opentelemetry/api";
import { logs } from "@opentelemetry/api-logs";
import { startBrowserSdk, type Instrumentation } from "@opentelemetry/browser-sdk";
import { browserDetector } from "@opentelemetry/browser-sdk/browser-detector";
import {
  createDefaultSessionIdGenerator,
  createLocalStorageSessionStore,
  createSessionLogRecordProcessor,
  createSessionManager,
  createSessionSpanProcessor,
} from "@opentelemetry/browser-sdk/session";
import { FetchInstrumentation } from "@opentelemetry/browser-instrumentation/experimental/fetch";
import { NavigationInstrumentation } from "@opentelemetry/browser-instrumentation/experimental/navigation";
import { NavigationTimingInstrumentation } from "@opentelemetry/browser-instrumentation/experimental/navigation-timing";
import { WebVitalsInstrumentation } from "@opentelemetry/browser-instrumentation/experimental/web-vitals";
import { XhrInstrumentation } from "@opentelemetry/browser-instrumentation/experimental/xhr";
import {
  AlwaysOnSampler,
  ParentBasedSampler,
  TraceIdRatioBasedSampler,
} from "@opentelemetry/sdk-trace";
import {
  Breadcrumbs,
  HttpBreadcrumbProcessor,
  NavigationBreadcrumbProcessor,
  recordClicks,
  recordConsole,
} from "./breadcrumbs.js";
import { Client } from "./client.js";
import { matches } from "./patterns.js";
import { Scope, ScopeLogRecordProcessor, ScopeSpanProcessor } from "./scope.js";
import { setCurrentClient } from "./state.js";
import type { InitOptions } from "./types.js";

export const DEFAULT_ENDPOINT = "https://superlog.sh/api/ingest";
const SCOPE_NAME = "@superlog/browser";

let started: { client: Client; stop: () => Promise<void> } | null = null;

// Starts error capture, sessions, tracing, and Web Vitals. Call it once, as
// early as possible, before the application renders.
export function init(options: InitOptions): Client | null {
  if (started) return started.client;
  if (options.disabled || typeof window === "undefined") return null;

  const endpoint = (options.endpoint ?? DEFAULT_ENDPOINT).replace(/\/+$/, "");
  const headers = {
    ...(options.ingestKey ? { authorization: `Bearer ${options.ingestKey}` } : {}),
    ...options.headers,
  };
  const isExport = (url: string) => url.startsWith(endpoint);
  const enabled = { clicks: true, console: true, fetch: true, navigation: true, navigationTiming: true, webVitals: true, xhr: true, ...options.instrumentations };

  const breadcrumbs = new Breadcrumbs(options.maxBreadcrumbs ?? 50, options.beforeBreadcrumb);
  const scope = new Scope();
  const sessions = createSessionManager({
    inactivityTimeout: options.session?.inactivityTimeout ?? 30 * 60_000,
    maxDuration: options.session?.maxDuration ?? 4 * 60 * 60_000,
    sessionIdGenerator: createDefaultSessionIdGenerator(),
    sessionStore: createLocalStorageSessionStore(),
  });
  void sessions.start();

  const propagateTo = options.tracePropagationTargets ?? [];
  const ignoreUrls = [new RegExp(`^${endpoint.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`), ...(options.ignoreUrls ?? [])];
  const sanitizeUrl = options.sanitizeUrl;
  const instrumentations: Instrumentation[] = [];
  if (enabled.navigation) instrumentations.push(new NavigationInstrumentation({ sanitizeUrl, useNavigationApiIfAvailable: true }));
  if (enabled.navigationTiming) instrumentations.push(new NavigationTimingInstrumentation());
  if (enabled.webVitals) instrumentations.push(new WebVitalsInstrumentation());
  if (enabled.fetch) instrumentations.push(new FetchInstrumentation({ ignoreUrls, propagateTraceHeaderCorsUrls: propagateTo, sanitizeUrl }));
  if (enabled.xhr) instrumentations.push(new XhrInstrumentation({ ignoreUrls, propagateTraceHeaderCorsUrls: propagateTo, sanitizeUrl }));

  const rate = options.tracesSampleRate ?? 1;
  const sdk = startBrowserSdk({
    exportConfig: { headers, url: endpoint },
    instrumentations,
    logLevel: options.debug ? "DEBUG" : "WARN",
    logs: {
      exportConfig: { headers, url: `${endpoint}/v1/logs` },
      processors: [
        createSessionLogRecordProcessor(sessions),
        new ScopeLogRecordProcessor(scope),
        new NavigationBreadcrumbProcessor(breadcrumbs),
        ...(options.logRecordProcessors ?? []),
      ],
    },
    resourceAttributes: {
      ...browserDetector.detect().attributes,
      ...(options.environment ? { "deployment.environment.name": options.environment } : {}),
      ...options.resourceAttributes,
    },
    serviceName: options.service,
    ...(options.release ? { serviceVersion: options.release } : {}),
    traces: {
      exportConfig: { headers, url: `${endpoint}/v1/traces` },
      ...(options.propagators ? { propagators: options.propagators } : {}),
      processors: [
        createSessionSpanProcessor(sessions),
        new ScopeSpanProcessor(scope),
        new HttpBreadcrumbProcessor(breadcrumbs, (url) => isExport(url) || matches(url, ignoreUrls)),
        ...(options.spanProcessors ?? []),
      ],
      sampler: rate >= 1 ? new ParentBasedSampler({ root: new AlwaysOnSampler() }) : new ParentBasedSampler({ root: new TraceIdRatioBasedSampler(rate) }),
    },
  });

  const client = new Client(options, logs.getLogger(SCOPE_NAME), breadcrumbs, scope);
  const stops = [
    listenForErrors(client),
    enabled.clicks ? recordClicks(breadcrumbs) : () => {},
    enabled.console ? recordConsole(breadcrumbs) : () => {},
  ];
  setCurrentClient(client);
  started = {
    client,
    stop: async () => {
      for (const stop of stops) stop();
      sessions.shutdown();
      await sdk.shutdown();
      // Unregisters the global providers so init can run again, as in tests.
      logs.disable();
      trace.disable();
      propagation.disable();
      context.disable();
    },
  };
  return client;
}

function listenForErrors(client: Client): () => void {
  const onError = (event: globalThis.ErrorEvent) => {
    client.captureException(event.error ?? event.message, { handled: false, mechanism: "onerror" });
  };
  const onRejection = (event: PromiseRejectionEvent) => {
    client.captureException(event.reason, { handled: false, mechanism: "onunhandledrejection" });
  };
  window.addEventListener("error", onError);
  window.addEventListener("unhandledrejection", onRejection);
  return () => {
    window.removeEventListener("error", onError);
    window.removeEventListener("unhandledrejection", onRejection);
  };
}

// Sends everything recorded so far. Call it before the page unloads on your
// own terms, such as before a redirect.
export async function flush(): Promise<void> {
  const loggerProvider = logs.getLoggerProvider() as { forceFlush?: () => Promise<void> };
  const tracerProvider = trace.getTracerProvider() as { getDelegate?: () => { forceFlush?: () => Promise<void> }; forceFlush?: () => Promise<void> };
  const delegate = tracerProvider.getDelegate?.() ?? tracerProvider;
  await Promise.all([loggerProvider.forceFlush?.(), delegate.forceFlush?.()]);
}

export async function shutdown(): Promise<void> {
  const current = started;
  started = null;
  setCurrentClient(null);
  await current?.stop();
}

import type { Context } from "@opentelemetry/api";
import type { LogRecordProcessor, SdkLogRecord } from "@opentelemetry/sdk-logs";
import type { ReadableSpan, Span, SpanProcessor } from "@opentelemetry/sdk-trace";
import type { Breadcrumb } from "./types.js";

const MAX_MESSAGE = 200;

// The most recent things that happened on the page, sent with each error.
export class Breadcrumbs {
  private readonly items: Breadcrumb[] = [];

  constructor(
    private readonly max: number,
    private readonly before?: (breadcrumb: Breadcrumb) => Breadcrumb | null,
  ) {}

  add(breadcrumb: Breadcrumb): void {
    if (this.max <= 0) return;
    let kept: Breadcrumb | null = { ...breadcrumb, timestamp: breadcrumb.timestamp ?? Date.now() };
    if (this.before) {
      try {
        kept = this.before(kept);
      } catch {
        // A failing hook keeps the breadcrumb as it was.
      }
    }
    if (!kept) return;
    this.items.push({ ...kept, message: kept.message.slice(0, MAX_MESSAGE), timestamp: kept.timestamp ?? Date.now() });
    if (this.items.length > this.max) this.items.splice(0, this.items.length - this.max);
  }

  // Oldest first, as JSON for a log attribute.
  serialize(): string | undefined {
    return this.items.length ? JSON.stringify(this.items) : undefined;
  }

  clear(): void {
    this.items.length = 0;
  }
}

// Navigations become breadcrumbs as the navigation instrumentation logs them.
export class NavigationBreadcrumbProcessor implements LogRecordProcessor {
  constructor(private readonly breadcrumbs: Breadcrumbs) {}

  onEmit(record: SdkLogRecord, _context?: Context): void {
    if (record.eventName !== "browser.navigation") return;
    const url = record.attributes["url.full"];
    if (typeof url === "string") this.breadcrumbs.add({ category: "navigation", message: url });
  }

  async forceFlush(): Promise<void> {}
  async shutdown(): Promise<void> {}
}

// Finished fetch and XMLHttpRequest spans become breadcrumbs.
export class HttpBreadcrumbProcessor implements SpanProcessor {
  constructor(
    private readonly breadcrumbs: Breadcrumbs,
    private readonly ignore: (url: string) => boolean,
  ) {}

  onStart(_span: Span, _context: Context): void {}

  onEnd(span: ReadableSpan): void {
    const method = span.attributes["http.request.method"];
    const url = span.attributes["url.full"];
    if (typeof method !== "string" || typeof url !== "string" || this.ignore(url)) return;
    const status = span.attributes["http.response.status_code"];
    const [seconds, nanos] = span.duration;
    const data: Record<string, string | number> = { duration_ms: Math.round(seconds * 1_000 + nanos / 1e6), method };
    if (typeof status === "number") data.status_code = status;
    this.breadcrumbs.add({
      category: "http",
      data,
      level: typeof status === "number" && status >= 400 ? "error" : "info",
      message: `${method} ${url.split("?")[0]}${typeof status === "number" ? ` ${status}` : ""}`,
    });
  }

  async forceFlush(): Promise<void> {}
  async shutdown(): Promise<void> {}
}

// A short selector for the clicked element: tag, id, and classes, with the
// nearest parent that has an id.
export function describeElement(element: Element): string {
  const part = (node: Element) => {
    const id = node.id ? `#${node.id}` : "";
    const classes = typeof node.className === "string" && node.className.trim()
      ? `.${node.className.trim().split(/\s+/).slice(0, 3).join(".")}`
      : "";
    return `${node.tagName.toLowerCase()}${id}${classes}`;
  };
  const parent = element.parentElement?.closest("[id]");
  const label = (element.getAttribute("aria-label") ?? element.textContent ?? "").trim().slice(0, 40);
  return `${parent && !element.id ? `${part(parent)} > ` : ""}${part(element)}${label ? ` "${label}"` : ""}`;
}

export function recordClicks(breadcrumbs: Breadcrumbs): () => void {
  const listener = (event: Event) => {
    const target = event.target;
    if (target instanceof Element) breadcrumbs.add({ category: "click", message: describeElement(target) });
  };
  document.addEventListener("click", listener, { capture: true, passive: true });
  return () => document.removeEventListener("click", listener, { capture: true });
}

const CONSOLE_LEVELS = { debug: "debug", error: "error", info: "info", log: "info", warn: "warning" } as const;

export function recordConsole(breadcrumbs: Breadcrumbs): () => void {
  const originals = new Map<keyof typeof CONSOLE_LEVELS, (...args: unknown[]) => void>();
  for (const method of Object.keys(CONSOLE_LEVELS) as (keyof typeof CONSOLE_LEVELS)[]) {
    const original = console[method];
    if (typeof original !== "function") continue;
    originals.set(method, original);
    console[method] = function (this: Console, ...args: unknown[]) {
      try {
        breadcrumbs.add({
          category: "console",
          level: CONSOLE_LEVELS[method],
          message: args.map((arg) => (typeof arg === "string" ? arg : safeString(arg))).join(" "),
        });
      } catch {
        // Recording never breaks the console.
      }
      return original.apply(this, args);
    };
  }
  return () => {
    for (const [method, original] of originals) console[method] = original;
  };
}

function safeString(value: unknown): string {
  if (value instanceof Error) return `${value.name}: ${value.message}`;
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}
